def _retired_summary_fact_ids(self, plan: Dict[str, Any]) -> set[str]:
    """Find cached reuses whose target was retired after the plan was written."""
    retired: set[str] = set()
    now = time.time()
    for decision in plan.get("decisions", []):
        if decision.get("action") != "reuse":
            continue
        target = decision.get("target") or {}
        if target.get("input_fact_id"):
            continue
        paragraph_hash = str(target.get("paragraph_hash", "") or "")
        paragraph = self.metadata_store.get_paragraph(paragraph_hash) if paragraph_hash else None
        invalid = not paragraph_active(paragraph)
        claim_id = str(target.get("claim_id", "") or "")
        if claim_id:
            claim = self.metadata_store.get_fact_claim(claim_id)
            invalid = invalid or claim is None or claim.get("status") != "active"
            if claim:
                valid_from = optional_float(claim.get("valid_from"))
                valid_to = optional_float(claim.get("valid_to"))
                invalid = invalid or claim.get("stability") == "uncertain"
                invalid = invalid or (valid_from is not None and valid_from > now)
                invalid = invalid or (valid_to is not None and valid_to <= now)
        if invalid:
            retired.add(str(decision["fact_id"]))
    while True:
        related = {str(d["fact_id"]) for d in plan.get("decisions", [])
            if str((d.get("target") or {}).get("input_fact_id", "")) in retired}
        before = len(retired)
        retired.update(related)
        if len(retired) == before:
            return retired

async def _refresh_retired_summary_plan(self, payload: Dict[str, Any]) -> Dict[str, Any]:
    old_plan = payload["plan"]
    retired = await asyncio.to_thread(self._retired_summary_fact_ids, old_plan)
    if not retired:
        return payload
    facts = [f for f in old_plan["facts"] if str(f["fact_id"]) not in retired]
    surviving = {str(f["fact_id"]) for f in facts}
    relations = [relation for index, relation in enumerate(payload.get("relations", []))
        if surviving.intersection(old_plan.get("relation_support", {}).get(str(index), []))]
    if facts:
        resolved_model = self._resolve_summary_model_task()
        task_name = resolved_model[0] if resolved_model else "utils"
        dedup = FactDeduplicator(self.metadata_store, self.embedding_manager, self.vector_store, task_name)
        plan = await dedup.plan(scope_type=old_plan["scope_type"], scope_id=old_plan["scope_id"],
            facts=facts, source=old_plan["source"], relations=relations)
    else:
        plan = {**old_plan, "facts": [], "decisions": [], "relation_support": {}}
    audit = {"at": time.time(), "reason": "retired_cached_dedup_target",
             "excluded_fact_ids": sorted(retired), "previous_plan": old_plan, "previous_payload": payload}
    refreshed = {**payload, "plan": plan, "relations": relations,
        "recovery_audit": [*payload.get("recovery_audit", []), audit]}
    meta = refreshed["metadata"]
    await asyncio.to_thread(self.metadata_store.record_summary_checkpoint,
        external_id=meta["external_id"], chat_id=plan["scope_id"],
        trigger_message_count=int(meta.get("trigger_message_count") or 0),
        phase="pending", result=refreshed)
    return refreshed

def _own_pending_summary_paragraph(self, paragraph_hash: str, payload: Dict[str, Any]) -> None:
    """Attach the observation to a legacy pending row owned by this checkpoint."""
    paragraph = self.metadata_store.get_paragraph(paragraph_hash)
    if paragraph is None:
        return
    meta = coerce_metadata_dict(paragraph.get("metadata"))
    if meta.get("dedup_phase") != "pending":
        return
    checked = {**paragraph, "metadata": {**meta, "dedup_phase": "complete"}}
    if not paragraph_active(checked):
        return
    observation = str(payload["plan"].get("source", {}).get("observation_id", "") or "")
    external_id = str(payload["metadata"].get("external_id", "") or "")
    if not observation or not external_id:
        return
    if meta.get("dedup_observation_id"):
        if meta["dedup_observation_id"] != observation:
            raise ValueError("待提交摘要段落属于另一个观察窗口")
        return
    reference = self.metadata_store.get_external_memory_ref(external_id)
    owned = meta.get("external_id") == external_id or (
        reference and str(reference.get("paragraph_hash", "")) == paragraph_hash
        and str(coerce_metadata_dict(reference.get("metadata")).get("chat_id", "")) == str(payload["plan"]["scope_id"]))
    if owned:
        self.metadata_store.update_paragraph_metadata(paragraph_hash,
            {"dedup_observation_id": observation}, merge=True)

